// ===================================================================
//  Vuelca las llamadas del inbox de voz a la conversacion de WhatsApp
//  del mismo contacto: nota privada con el resumen y el audio adjunto.
// ===================================================================

// --- Que cuenta e inboxes de Chatwoot
const CUENTA          = 5;   // Franquicias
const INBOX_LLAMADAS  = 9;   // Voice (+34872437354)
const INBOX_WHATSAPP  = 7;   // WhatsApp

// --- MODO PRUEBA -----------------------------------------------------
// Con un numero, solo se procesa esa conversacion del inbox de llamadas.
// Con null, se procesan todas. Dejalo fijado mientras se valida.
const SOLO_ESTA_CONVERSACION = 44;   // conversacion de prueba (contacto Coral, +34000000000)

// --- BORRADO ---------------------------------------------------------
// Cuando una llamada no deja grabacion (no la cogen, falla), la conversacion
// del inbox de llamadas no aporta nada y se puede borrar. El CONTACTO NUNCA
// se borra: solo la conversacion.
// De momento en false: el nodo BorrarLlamadaSinAudio ademas esta desactivado.
// Para activarlo hay que poner esto en true Y habilitar ese nodo.
const BORRAR_LLAMADAS_SIN_AUDIO = false;

// --- Margen antes de dar una llamada por "sin audio" ------------------
// Twilio tarda un poco en subir la grabacion despues de colgar. Si damos la
// llamada por perdida antes de tiempo, borrariamos conversaciones que si
// tenian audio.
const MINUTOS_DE_GRACIA = 15;

// --- Cuando se considera que la llamada SI se atendio ------------------
// Hay llamadas que Twilio marca "completed" y duran 12-21 s pero no dejan
// grabacion: esas se cogieron y hablaron. Borrarlas perderia el unico
// rastro de una llamada real, asi que se apartan para revisar a mano en
// lugar de tratarlas como no atendidas.
const SEGUNDOS_PARA_CONSIDERAR_ATENDIDA = 5;

return [{ json: {
  CUENTA, INBOX_LLAMADAS, INBOX_WHATSAPP,
  SOLO_ESTA_CONVERSACION, BORRAR_LLAMADAS_SIN_AUDIO, MINUTOS_DE_GRACIA,
  SEGUNDOS_PARA_CONSIDERAR_ATENDIDA,
} }];

const cfg  = $('Configuracion').first().json;
const conv = $('Por Cada Llamada').first().json;
const mensajes = $input.first().json.payload || [];
const ahora = Math.floor(Date.now() / 1000);

// Llamadas ya volcadas, guardadas como atributo de la conversacion de llamada.
const yaVolcadas = String(conv.custom_attributes?.llamadas_volcadas || '')
  .split(',').map(s => s.trim()).filter(Boolean);

// Cada mensaje de tipo voice_call trae su objeto `call`.
const llamadas = mensajes.filter(m => m.call).map(m => m.call);

const base = {
  conv_llamada: conv.id,
  contacto_id: conv.meta?.sender?.id ?? null,
  nombre: conv.meta?.sender?.name ?? null,
  telefono: conv.meta?.sender?.phone_number ?? null,
  llamadas_en_conversacion: llamadas.length,
  ya_volcadas: yaVolcadas,
};
const salida = (accion, motivo, extra) => [{ json: { ...base, accion, motivo, ...(extra || {}) } }];

if (!llamadas.length) {
  return salida('esperar', 'La conversacion no tiene ninguna llamada registrada.');
}

// Una llamada esta terminada cuando ya no suena ni esta en curso.
const terminada = (c) => !['ringing', 'in-progress', 'queued', 'initiated'].includes(c.status);
const pasoLaGracia = (c) => {
  const fin = c.ended_at || c.started_at;
  return fin ? (ahora - fin) >= cfg.MINUTOS_DE_GRACIA * 60 : false;
};

// 1) Llamadas con grabacion que todavia no se han volcado, la mas antigua primero.
const pendientes = llamadas
  .filter(c => c.recording_url && !yaVolcadas.includes(String(c.id)))
  .sort((a, b) => (a.started_at || 0) - (b.started_at || 0));

if (pendientes.length) {
  const c = pendientes[0];
  const inicio = c.started_at ? new Date(c.started_at * 1000) : null;
  return salida('volcar', `Llamada ${c.id} con grabacion de ${c.duration_seconds || 0} s.`, {
    call_id: c.id,
    grabacion_url: c.recording_url,
    duracion_segundos: c.duration_seconds || 0,
    estado_llamada: c.status,
    direccion: c.direction,
    agente: c.accepted_by_agent_name || null,
    transcripcion_previa: c.transcript || null,
    fecha_llamada: inicio ? inicio.toISOString() : null,
    pendientes_restantes: pendientes.length - 1,
  });
}

// 2) Sin grabacion en ninguna llamada. Solo entonces la conversacion es
//    candidata a borrarse: si alguna llamada tuvo audio, no se toca.
const algunaConGrabacion = llamadas.some(c => c.recording_url);
const todasTerminadas    = llamadas.every(terminada);
const todasConGracia     = llamadas.every(pasoLaGracia);

if (!algunaConGrabacion && todasTerminadas && todasConGracia) {
  // Una llamada que conecto y duro lo suficiente SI se atendio, aunque no
  // haya grabacion. Esa conversacion no se borra: se aparta para revisar.
  const atendidas = llamadas.filter(c =>
    c.status === 'completed' && (c.duration_seconds || 0) >= cfg.SEGUNDOS_PARA_CONSIDERAR_ATENDIDA);

  if (atendidas.length) {
    const segs = atendidas.map(c => `${c.duration_seconds}s`).join(', ');
    return salida('esperar',
      `Atendida (${segs}) pero sin grabacion. No se borra: revisar a mano.`, {
      call_id: atendidas[atendidas.length - 1].id,
      estado_llamada: atendidas[atendidas.length - 1].status,
      revisar_a_mano: true,
    });
  }

  const estados = [...new Set(llamadas.map(c => c.status))].join(', ');
  return salida('sin_audio', `Ninguna de las ${llamadas.length} llamadas se atendio (${estados}).`, {
    call_id: llamadas[llamadas.length - 1].id,
    estado_llamada: llamadas[llamadas.length - 1].status,
  });
}

if (!todasTerminadas)  return salida('esperar', 'Hay una llamada todavia en curso.');
if (!todasConGracia)   return salida('esperar', `Aun dentro del margen de ${cfg.MINUTOS_DE_GRACIA} min por si sube la grabacion.`);
return salida('esperar', 'Todas las llamadas con grabacion ya estaban volcadas.');

const cfg     = $('Configuracion').first().json;
const llamada = $('AnalizarLlamada').first().json;
const lista   = $input.first().json.payload || [];

// Se busca la conversacion de WhatsApp del MISMO contacto. En Chatwoot el
// contacto es unico por cuenta y tiene una conversacion por inbox, asi que
// el enlace llamada -> WhatsApp es directo.
const deWhatsapp = lista
  .filter(c => c.inbox_id === cfg.INBOX_WHATSAPP)
  .sort((a, b) => (b.last_activity_at || 0) - (a.last_activity_at || 0));

// Si el contacto no tiene WhatsApp, la nota se queda en la propia
// conversacion de la llamada. Nunca se pierde el resumen.
const destino = deWhatsapp[0];

return [{ json: {
  ...llamada,
  conversacion_destino: destino ? destino.id : llamada.conv_llamada,
  hay_whatsapp: Boolean(destino),
  inbox_destino: destino ? destino.inbox_id : cfg.INBOX_LLAMADAS,
} }];

// La grabacion se descarga con un nombre sin extension (RE649258...) y eso
// hace que la API de transcripcion la rechace por formato desconocido.
// Aqui se le pone nombre, extension y tipo correctos.
const items = $input.all();

for (const item of items) {
  const bin = item.binary?.data;
  if (!bin) continue;
  bin.fileName      = `llamada-${item.json.call_id || 's-n'}.wav`;
  bin.fileExtension = 'wav';
  bin.mimeType      = 'audio/wav';
}

return items;

// La grabacion se descarga con un nombre sin extension (RE649258...) y eso
// hace que la API de transcripcion la rechace por formato desconocido.
// Aqui se le pone nombre, extension y tipo correctos.
const items = $input.all();

for (const item of items) {
  const bin = item.binary?.data;
  if (!bin) continue;
  bin.fileName      = `llamada-${item.json.call_id || 's-n'}.wav`;
  bin.fileExtension = 'wav';
  bin.mimeType      = 'audio/wav';
}

return items;

