=Datos de la llamada:
- Fecha: {{ $('LocalizarDestino').first().json.fecha_llamada }}
- Duracion: {{ $('LocalizarDestino').first().json.duracion_segundos }} segundos
- Sentido: {{ $('LocalizarDestino').first().json.direccion }}
- Agente: {{ $('LocalizarDestino').first().json.agente }}
- Contacto: {{ $('LocalizarDestino').first().json.nombre }}

Transcripcion:
{{ $json.text }}

parameters.jsCode:
const d = $('LocalizarDestino').first().json;
const resumen = ($input.first().json.text || $input.first().json.output || '').trim();

const fecha = d.fecha_llamada ? new Date(d.fecha_llamada) : null;
const cuando = fecha
  ? fecha.toLocaleString('es-ES', { timeZone: 'Europe/Madrid', day: '2-digit', month: '2-digit',
                                    year: 'numeric', hour: '2-digit', minute: '2-digit' })
  : 'fecha desconocida';

const seg = d.duracion_segundos || 0;
const dur = seg >= 60 ? `${Math.floor(seg / 60)} min ${seg % 60} s` : `${seg} s`;
const sentido = d.direccion === 'outgoing' ? 'saliente' : d.direccion === 'incoming' ? 'entrante' : (d.direccion || '');

const cabecera = [
  `LLAMADA ${sentido} · ${cuando} · ${dur}`,
  d.agente ? `Atendida por ${d.agente}` : null,
].filter(Boolean).join('\n');

const pie = `Grabacion adjunta · llamada #${d.call_id}`;
const aviso = d.hay_whatsapp ? null
  : 'Este contacto no tiene conversacion de WhatsApp, asi que la nota se queda aqui.';

const contenido = [cabecera, '', resumen, '', aviso, pie].filter(x => x !== null).join('\n');

return [{ json: { ...d, resumen, contenido_nota: contenido } }];
